-- SYSTEM: reference SQLite relational design for a future synced backend.
-- The shipped static website uses browser-local JSON; this is not a live database.
PRAGMA foreign_keys = ON;
CREATE TABLE player (id TEXT PRIMARY KEY, name TEXT NOT NULL, start_date TEXT NOT NULL, daily_minutes INTEGER NOT NULL CHECK(daily_minutes BETWEEN 1 AND 720), target_role TEXT NOT NULL);
CREATE TABLE curriculum_day (day INTEGER PRIMARY KEY CHECK(day BETWEEN 1 AND 90), week INTEGER NOT NULL, phase INTEGER NOT NULL CHECK(phase BETWEEN 1 AND 3), title TEXT NOT NULL, tools TEXT NOT NULL, technique TEXT NOT NULL, task TEXT NOT NULL, acceptance TEXT NOT NULL, speaking_drill TEXT NOT NULL, resource_url TEXT NOT NULL, is_boss INTEGER NOT NULL DEFAULT 0);
CREATE TABLE quest_template (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, recurrence TEXT NOT NULL CHECK(recurrence IN ('daily','curriculum')), xp INTEGER NOT NULL CHECK(xp>=0), gold INTEGER NOT NULL CHECK(gold>=0), str_points INTEGER NOT NULL DEFAULT 0, agi_points INTEGER NOT NULL DEFAULT 0, vit_points INTEGER NOT NULL DEFAULT 0, int_points INTEGER NOT NULL DEFAULT 0, per_points INTEGER NOT NULL DEFAULT 0);
CREATE TABLE quest_instance (id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES player(id), template_id TEXT NOT NULL REFERENCES quest_template(id), curriculum_day INTEGER REFERENCES curriculum_day(day), scheduled_date TEXT NOT NULL, completed_date TEXT, evidence TEXT NOT NULL DEFAULT '', speaking_note TEXT NOT NULL DEFAULT '', UNIQUE(player_id, template_id, scheduled_date));
CREATE TABLE reward_event (id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES player(id), source_key TEXT NOT NULL, event_date TEXT NOT NULL, created_at TEXT NOT NULL, xp INTEGER NOT NULL DEFAULT 0 CHECK(xp>=0), gold_delta INTEGER NOT NULL DEFAULT 0, str_delta INTEGER NOT NULL DEFAULT 0, agi_delta INTEGER NOT NULL DEFAULT 0, vit_delta INTEGER NOT NULL DEFAULT 0, int_delta INTEGER NOT NULL DEFAULT 0, per_delta INTEGER NOT NULL DEFAULT 0, UNIQUE(player_id, source_key));
CREATE TABLE daily_log (player_id TEXT NOT NULL REFERENCES player(id), log_date TEXT NOT NULL, study_minutes INTEGER NOT NULL DEFAULT 0 CHECK(study_minutes BETWEEN 0 AND 720), exempt INTEGER NOT NULL DEFAULT 0, recovery_done INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(player_id,log_date));
CREATE TABLE day_closure (player_id TEXT NOT NULL REFERENCES player(id), log_date TEXT NOT NULL, missed_count INTEGER NOT NULL CHECK(missed_count BETWEEN 0 AND 7), closed_at TEXT NOT NULL, recovery_due TEXT NOT NULL, PRIMARY KEY(player_id,log_date));
CREATE TABLE recovery_task (id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES player(id), due_date TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', done INTEGER NOT NULL DEFAULT 0, completed_at TEXT);
CREATE UNIQUE INDEX one_active_recovery_per_player ON recovery_task(player_id) WHERE done=0;
CREATE TABLE recovery_missed_day (task_id TEXT NOT NULL REFERENCES recovery_task(id), player_id TEXT NOT NULL, missed_date TEXT NOT NULL, PRIMARY KEY(task_id,missed_date), FOREIGN KEY(player_id,missed_date) REFERENCES day_closure(player_id,log_date));
CREATE TABLE raid (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('dungeon','boss')), rank TEXT CHECK(rank IN ('E','D','C','B','A','S')), start_day INTEGER NOT NULL REFERENCES curriculum_day(day), end_day INTEGER NOT NULL REFERENCES curriculum_day(day), xp INTEGER NOT NULL, gold INTEGER NOT NULL, CHECK(end_day>=start_day));
CREATE TABLE raid_requirement (raid_id TEXT NOT NULL REFERENCES raid(id), curriculum_day INTEGER NOT NULL REFERENCES curriculum_day(day), PRIMARY KEY(raid_id,curriculum_day));
CREATE TABLE raid_clear (player_id TEXT NOT NULL REFERENCES player(id), raid_id TEXT NOT NULL REFERENCES raid(id), clear_date TEXT NOT NULL, evidence TEXT NOT NULL, check_complete INTEGER NOT NULL CHECK(check_complete=1), check_validated INTEGER NOT NULL CHECK(check_validated=1), check_explainable INTEGER NOT NULL CHECK(check_explainable=1), PRIMARY KEY(player_id,raid_id));
CREATE TABLE shop_item (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, gold_cost INTEGER NOT NULL CHECK(gold_cost>0));
CREATE TABLE purchase (id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES player(id), item_id TEXT NOT NULL REFERENCES shop_item(id), name_snapshot TEXT NOT NULL, cost_snapshot INTEGER NOT NULL CHECK(cost_snapshot>0), purchased_date TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, used_date TEXT);
CREATE TABLE shadow (id TEXT PRIMARY KEY, raid_id TEXT NOT NULL UNIQUE REFERENCES raid(id), name TEXT NOT NULL, template_text TEXT NOT NULL);
CREATE TABLE player_shadow (player_id TEXT NOT NULL REFERENCES player(id), shadow_id TEXT NOT NULL REFERENCES shadow(id), active INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(player_id,shadow_id));
CREATE VIEW player_totals AS SELECT p.id, COALESCE(SUM(e.xp),0) AS total_exp, COALESCE(SUM(e.gold_delta),0) AS gold, 10+COALESCE(SUM(e.str_delta),0) AS str, 10+COALESCE(SUM(e.agi_delta),0) AS agi, 10+COALESCE(SUM(e.vit_delta),0) AS vit, 10+COALESCE(SUM(e.int_delta),0) AS intelligence, 10+COALESCE(SUM(e.per_delta),0) AS perception FROM player p LEFT JOIN reward_event e ON e.player_id=p.id GROUP BY p.id;
-- Purchases and awards must run in transactions. Check wallet and write a uniquely
-- keyed debit atomically. Enforce raid eligibility, immutable rewards, sign-off
-- and shadow unlocks in server code before adopting this reference schema.
